CREATE TABLE public.reporting_obligations (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), user_id uuid NOT NULL REFERENCES auth.users(id), scope_type text NOT NULL CHECK(scope_type IN ('program','project')), program_id uuid REFERENCES public.programs(id), project_id uuid REFERENCES public.projects(id), form_id uuid REFERENCES public.me_forms(id), cadence text NOT NULL CHECK(cadence IN ('weekly','fortnightly','monthly','quarterly')), grace_days integer NOT NULL DEFAULT 3 CHECK(grace_days BETWEEN 0 AND 90), starts_on date NOT NULL DEFAULT CURRENT_DATE, ends_on date, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid DEFAULT auth.uid() REFERENCES auth.users(id), updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid REFERENCES auth.users(id), deleted_at timestamptz,
 CHECK((scope_type='program' AND program_id IS NOT NULL AND project_id IS NULL) OR (scope_type='project' AND project_id IS NOT NULL AND program_id IS NULL)), CHECK(ends_on IS NULL OR ends_on>=starts_on));
GRANT SELECT,INSERT,UPDATE ON public.reporting_obligations TO authenticated;
GRANT ALL ON public.reporting_obligations TO service_role;
ALTER TABLE public.reporting_obligations ENABLE ROW LEVEL SECURITY;
CREATE INDEX ON public.reporting_obligations(organization_id,user_id);
CREATE INDEX ON public.me_form_submissions(organization_id,submitted_by,submission_date) WHERE deleted_at IS NULL;
CREATE FUNCTION public.can_manage_reporting(_org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (public.user_belongs_to_org(auth.uid(),_org) OR public.has_role(auth.uid(),'admin')) AND (public.user_is_org_elevated(auth.uid(),_org) OR public.user_has_permission(auth.uid(),_org,'hr','edit','staff') OR public.user_has_permission(auth.uid(),_org,'hr','create','staff') OR public.user_has_permission(auth.uid(),_org,'users','manage','roles')) $$;
CREATE FUNCTION public.can_read_reporting(_org uuid,_user uuid,_program uuid,_project uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (public.user_belongs_to_org(auth.uid(),_org) OR public.has_role(auth.uid(),'admin')) AND NOT app_private.user_is_donor_for_org(auth.uid(),_org) AND CASE WHEN public.user_is_field_scoped(auth.uid(),_org) THEN _user=auth.uid() WHEN public.can_manage_reporting(_org) THEN true WHEN public.user_is_program_scoped(auth.uid(),_org) OR EXISTS(SELECT 1 FROM programme_team WHERE org_id=_org AND staff_id=auth.uid() AND is_lead AND end_date IS NULL) THEN _program IN(SELECT public.user_assigned_program_ids(auth.uid(),_org)) OR _project IN(SELECT public.user_assigned_project_ids(auth.uid(),_org)) OR EXISTS(SELECT 1 FROM projects WHERE id=_project AND program_id IN(SELECT public.user_assigned_program_ids(auth.uid(),_org))) ELSE _user=auth.uid() END $$;
REVOKE ALL ON FUNCTION public.can_manage_reporting(uuid),public.can_read_reporting(uuid,uuid,uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_manage_reporting(uuid),public.can_read_reporting(uuid,uuid,uuid,uuid) TO authenticated,service_role;
CREATE POLICY reporting_read ON public.reporting_obligations FOR SELECT TO authenticated USING(deleted_at IS NULL AND public.can_read_reporting(organization_id,user_id,program_id,project_id));
CREATE POLICY reporting_create ON public.reporting_obligations FOR INSERT TO authenticated WITH CHECK(public.can_manage_reporting(organization_id));
CREATE POLICY reporting_update ON public.reporting_obligations FOR UPDATE TO authenticated USING(public.can_manage_reporting(organization_id)) WITH CHECK(public.can_manage_reporting(organization_id));
CREATE FUNCTION public.guard_reporting_obligation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 IF TG_OP='INSERT' THEN NEW.starts_on:=GREATEST(NEW.starts_on,CURRENT_DATE); NEW.created_by:=auth.uid(); ELSE IF NEW.organization_id<>OLD.organization_id OR NEW.user_id<>OLD.user_id OR NEW.scope_type<>OLD.scope_type OR NEW.program_id IS DISTINCT FROM OLD.program_id OR NEW.project_id IS DISTINCT FROM OLD.project_id OR NEW.starts_on<>OLD.starts_on OR NEW.cadence<>OLD.cadence OR NEW.form_id IS DISTINCT FROM OLD.form_id THEN RAISE EXCEPTION 'End the obligation and create a new one to change its reporting schedule'; END IF; END IF;
 IF NOT public.user_belongs_to_org(NEW.user_id,NEW.organization_id) THEN RAISE EXCEPTION 'Staff must belong to this organisation'; END IF;
 IF NEW.scope_type='program' AND NOT EXISTS(SELECT 1 FROM programs WHERE id=NEW.program_id AND organization_id=NEW.organization_id AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Programme not in organisation'; END IF;
 IF NEW.scope_type='project' AND NOT EXISTS(SELECT 1 FROM projects WHERE id=NEW.project_id AND organization_id=NEW.organization_id AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Project not in organisation'; END IF;
 IF (NEW.scope_type='program' AND NEW.program_id NOT IN(SELECT public.user_assigned_program_ids(NEW.user_id,NEW.organization_id))) OR (NEW.scope_type='project' AND NEW.project_id NOT IN(SELECT public.user_assigned_project_ids(NEW.user_id,NEW.organization_id))) THEN RAISE EXCEPTION 'Staff must be on the selected team'; END IF;
 IF NEW.form_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM me_forms WHERE id=NEW.form_id AND organization_id=NEW.organization_id AND deleted_at IS NULL AND (program_id IS NULL OR program_id=NEW.program_id OR program_id=(SELECT program_id FROM projects WHERE id=NEW.project_id)) AND (project_id IS NULL OR project_id=NEW.project_id)) THEN RAISE EXCEPTION 'Form does not match organisation and scope'; END IF;
 NEW.updated_at:=now(); NEW.updated_by:=auth.uid(); RETURN NEW; END $$;
CREATE TRIGGER guard_reporting BEFORE INSERT OR UPDATE ON public.reporting_obligations FOR EACH ROW EXECUTE FUNCTION public.guard_reporting_obligation();
CREATE FUNCTION public.get_reporting_ledger(_org_id uuid,_from date,_to date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN
 IF NOT (public.user_belongs_to_org(auth.uid(),_org_id) OR public.has_role(auth.uid(),'admin')) OR app_private.user_is_donor_for_org(auth.uid(),_org_id) THEN RAISE EXCEPTION 'Organisation access required'; END IF;
 IF _from IS NULL OR _to IS NULL OR _to<_from OR _to-_from>366 THEN RAISE EXCEPTION 'Select a range of at most 366 days'; END IF;
 SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.staff_name,r.period_start),'[]') INTO result FROM (
 SELECT o.id obligation_id,o.user_id,COALESCE(p.full_name,'Staff member') staff_name,o.scope_type,COALESCE(o.program_id,pr.program_id) program_id,o.project_id,COALESCE(prog.name,parent.name) program_name,COALESCE(pr.name,prog.name) scope_name,COALESCE(f.name,'Any scope report') form_name,o.cadence,o.grace_days,period.start::date period_start,LEAST((period.start+step.duration-interval '1 day')::date,COALESCE(o.ends_on,'infinity'::date)) period_end,
 CASE WHEN EXISTS(SELECT 1 FROM me_form_submissions s WHERE s.organization_id=o.organization_id AND s.submitted_by=o.user_id AND s.deleted_at IS NULL AND s.submission_date BETWEEN period.start::date AND LEAST((period.start+step.duration-interval '1 day')::date,COALESCE(o.ends_on,'infinity'::date)) AND (o.form_id IS NULL OR s.form_id=o.form_id) AND ((o.scope_type='program' AND s.program_id=o.program_id) OR(o.scope_type='project' AND s.project_id=o.project_id))) THEN 'submitted' WHEN CURRENT_DATE>LEAST((period.start+step.duration-interval '1 day')::date,COALESCE(o.ends_on,'infinity'::date))+o.grace_days THEN 'overdue' ELSE 'pending' END status,
 (SELECT max(a.created_at) FROM audit_logs a WHERE a.entity_id=o.id AND a.event_type='reporting_nudge' AND a.metadata->>'period_start'=period.start::date::text) last_nudged_at
 FROM reporting_obligations o LEFT JOIN profiles p ON p.user_id=o.user_id LEFT JOIN programs prog ON prog.id=o.program_id LEFT JOIN projects pr ON pr.id=o.project_id LEFT JOIN programs parent ON parent.id=pr.program_id LEFT JOIN me_forms f ON f.id=o.form_id
 CROSS JOIN LATERAL(SELECT CASE o.cadence WHEN 'weekly' THEN interval '7 days' WHEN 'fortnightly' THEN interval '14 days' WHEN 'monthly' THEN interval '1 month' ELSE interval '3 months' END duration)step
 CROSS JOIN LATERAL generate_series(o.starts_on::timestamp,LEAST(_to,CURRENT_DATE,COALESCE(o.ends_on,_to))::timestamp,step.duration)period(start)
 WHERE o.organization_id=_org_id AND o.is_active AND o.deleted_at IS NULL AND public.can_read_reporting(o.organization_id,o.user_id,o.program_id,o.project_id) AND (period.start+step.duration-interval '1 day')::date>=_from
 )r; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.get_reporting_ledger(uuid,date,date) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_reporting_ledger(uuid,date,date) TO authenticated;
CREATE FUNCTION public.reporting_team_options(_org_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NOT public.can_manage_reporting(_org_id) OR app_private.user_is_donor_for_org(auth.uid(),_org_id) THEN RAISE EXCEPTION 'HR or role-management permission required'; END IF;
 RETURN jsonb_build_object('programs',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'name',name)),'[]') FROM programs WHERE organization_id=_org_id AND deleted_at IS NULL),'projects',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'name',name,'program_id',program_id)),'[]') FROM projects WHERE organization_id=_org_id AND deleted_at IS NULL),'staff',(SELECT COALESCE(jsonb_agg(jsonb_build_object('user_id',om.user_id,'name',COALESCE(p.full_name,'Staff member'),'program_ids',(SELECT COALESCE(jsonb_agg(x),'[]') FROM public.user_assigned_program_ids(om.user_id,_org_id)x),'project_ids',(SELECT COALESCE(jsonb_agg(x),'[]') FROM public.user_assigned_project_ids(om.user_id,_org_id)x))),'[]') FROM organization_members om LEFT JOIN profiles p ON p.user_id=om.user_id WHERE om.organization_id=_org_id),'forms',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'name',name,'program_id',program_id,'project_id',project_id)),'[]') FROM me_forms WHERE organization_id=_org_id AND deleted_at IS NULL)); END $$;
REVOKE ALL ON FUNCTION public.reporting_team_options(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.reporting_team_options(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION app_private.work_management_source_org(_type text,_id uuid,_org uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE ok boolean:=false; BEGIN CASE _type WHEN 'life_event' THEN SELECT EXISTS(SELECT 1 FROM public.life_events WHERE id=_id AND organization_id=_org AND deleted_at IS NULL) INTO ok; WHEN 'vulnerability_assessment' THEN SELECT EXISTS(SELECT 1 FROM public.vulnerability_assessments WHERE id=_id AND organization_id=_org) INTO ok; WHEN 'need' THEN SELECT EXISTS(SELECT 1 FROM public.beneficiary_needs WHERE id=_id AND organization_id=_org) INTO ok; WHEN 'home_visit' THEN SELECT EXISTS(SELECT 1 FROM public.home_visits WHERE id=_id AND organization_id=_org AND deleted_at IS NULL) INTO ok; WHEN 'school_visit' THEN SELECT EXISTS(SELECT 1 FROM public.school_visits WHERE id=_id AND organization_id=_org AND deleted_at IS NULL) INTO ok; WHEN 'donor_request' THEN SELECT EXISTS(SELECT 1 FROM public.donation_intents WHERE id=_id AND organization_id=_org) INTO ok; WHEN 'reporting_obligation' THEN SELECT EXISTS(SELECT 1 FROM public.reporting_obligations WHERE id=_id AND organization_id=_org AND deleted_at IS NULL) INTO ok; ELSE RAISE EXCEPTION 'Unsupported task source type'; END CASE; RETURN ok; END $$;
CREATE FUNCTION public.prepare_reporting_nudge(_obligation uuid,_period date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,app_private AS $$ DECLARE o reporting_obligations; r jsonb; task uuid; key text; contact text; BEGIN
 SELECT * INTO o FROM reporting_obligations WHERE id=_obligation AND deleted_at IS NULL;
 IF o.id IS NULL OR NOT public.can_manage_reporting(o.organization_id) OR app_private.user_is_donor_for_org(auth.uid(),o.organization_id) THEN RAISE EXCEPTION 'HR or role-management permission required'; END IF;
 SELECT value INTO r FROM jsonb_array_elements(public.get_reporting_ledger(o.organization_id,_period,_period)) WHERE value->>'obligation_id'=o.id::text AND value->>'period_start'=_period::text AND value->>'status'='overdue';
 IF r IS NULL THEN RAISE EXCEPTION 'This reporting period is not overdue'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(o.id::text||_period::text,0));
 key:='reporting:'||o.organization_id::text||':'||o.id::text||':'||_period::text;
 -- The existing source-task RPC remains the sole task creation path; this permission-checked transaction calls its service-authorised implementation.
 PERFORM set_config('request.jwt.claim.role','service_role',true);
 task:=public.create_or_get_source_task(o.organization_id,'reporting_overdue:'||_period::text,'reporting_obligation',o.id,'Submit reporting obligation',NULL,o.user_id,'medium',(r->>'period_end')::date,o.program_id,o.project_id,NULL,false);
 IF NOT EXISTS(SELECT 1 FROM audit_logs WHERE entity_id=o.id AND event_type='reporting_nudge' AND metadata->>'period_start'=_period::text) THEN
 INSERT INTO audit_logs(event_type,entity_type,entity_id,user_id,metadata) VALUES('reporting_nudge','reporting_obligation',o.id,auth.uid(),jsonb_build_object('organization_id',o.organization_id,'period_start',_period,'period_end',r->>'period_end','task_id',task,'idempotency_key',key)); END IF;
 SELECT email INTO contact FROM profiles WHERE user_id=o.user_id;
 RETURN r||jsonb_build_object('organization_id',o.organization_id,'recipient_user_id',o.user_id,'contact',contact,'task_id',task,'idempotency_key',key); END $$;
REVOKE ALL ON FUNCTION public.prepare_reporting_nudge(uuid,date) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.prepare_reporting_nudge(uuid,date) TO authenticated;
NOTIFY pgrst, 'reload schema';